{"cards": [{"node_code": "N_866b0df9a66f9625", "definition": "研究各类杀鼠剂（如抗凝血类、磷化锌、氟乙酰胺等）及灭鼠药中毒的临床表现、诊断、特异性解毒治疗及法医鉴定。", "boundary": "本节点聚焦于专门用于灭鼠的化学制剂引起的中毒事件。涵盖急性与慢性中毒机制、误服或自杀/他杀案例的救治与鉴定。与工业农业毒物区别在于用途特定为灭鼠；与医用药物中毒区别在于非治疗性药物。", "includes": ["抗凝血类杀鼠剂中毒诊断与维生素K1治疗", "磷化锌、氟乙酰胺等剧毒灭鼠药中毒救治", "杀鼠剂中毒的法医毒物分析与死因推断"], "excludes": ["非灭鼠用途的农药中毒", "医用抗凝药物（如华法林）过量中毒"], "sibling_distinctions": [{"other_code": "N_736bb7e09acaa63d", "rule": "工业与农业毒物侧重生产、加工或种植过程中的职业/环境暴露，杀鼠剂侧重特定灭鼠用途制剂的误服或故意摄入。"}, {"other_code": "N_6c51fa6883b3b657", "rule": "医用药物中毒指处方或非处方药在治疗剂量或过量下的不良反应，杀鼠剂中毒指非医疗用途的灭鼠化学品摄入。"}], "cross_boundary_rule": "涉及灭鼠专用化学品中毒主挂载本节点；涉及通用农药中毒主挂载工业与农业毒物；涉及治疗性抗凝药过量主挂载医用药物中毒。"}, {"node_code": "N_388d6b7b7d096fa7", "definition": "研究有毒蘑菇（毒蕈）中毒的菌种鉴别、毒素分类、临床表现、特异性治疗及法医鉴定。", "boundary": "本节点聚焦于真菌界毒蕈引起的中毒。涵盖鹅膏毒肽、毒蕈碱、胃肠毒素等不同毒素类型的机制与救治。与蛇毒区别在于生物来源为真菌；与工业毒物区别在于天然生物毒素。", "includes": ["鹅膏菌、丝膜菌等常见毒蕈中毒诊断与救治", "毒蕈毒素（如α-鹅膏毒肽）的作用机制与拮抗治疗", "毒蕈中毒的法医鉴定与菌种形态学分析"], "excludes": ["蛇毒、蜂毒等动物源性毒素中毒", "人工合成化学毒物中毒"], "sibling_distinctions": [{"other_code": "N_75666d8101784713", "rule": "蛇毒与动物毒侧重脊椎动物（蛇、蜂、蜘蛛等）分泌的毒素，毒蕈侧重真菌产生的次生代谢毒素。"}, {"other_code": "N_7e844cfb9aba1d2d", "rule": "金属与化学毒物侧重无机或有机化学合成物质，毒蕈侧重天然生物来源的真菌毒素。"}], "cross_boundary_rule": "涉及真菌毒素中毒主挂载本节点；涉及动物毒素中毒主挂载蛇毒与动物毒；涉及化学合成毒物主挂载金属与化学毒物。"}, {"node_code": "N_1ff4a66309ab0a01", "definition": "研究物理因素（如辐射、高温、低温、电流、噪声等）对人体造成的急性或慢性损伤、诊断、救治及法医鉴定。", "boundary": "本节点聚焦于非化学性物理能量或环境因素引起的中毒/损伤。涵盖放射病、电击伤、热射病、冻伤等。与化学毒物区别在于致伤因子为物理能量；与职业卫生区别在于侧重个体急性/亚急性损伤救治。", "includes": ["电离辐射与非电离辐射损伤的诊断与救治", "电击伤、雷击伤及电流对机体的损伤机制", "高温（热射病）、低温（冻伤）及噪声性损伤的临床处理"], "excludes": ["化学毒物引起的中毒", "机械性创伤（如骨折、切割伤）"], "sibling_distinctions": [{"other_code": "N_7e844cfb9aba1d2d", "rule": "金属与化学毒物侧重化学物质摄入或接触引起的毒性，物理因素中毒侧重物理能量（辐射、电、热等）造成的损伤。"}, {"other_code": "N_736bb7e09acaa63d", "rule": "工业与农业毒物侧重化学制剂，物理因素中毒侧重物理环境因素，即使发生在工业场景中，若致伤因子为物理能量则归入本节点。"}], "cross_boundary_rule": "涉及物理能量（辐射、电、热等）损伤主挂载本节点；涉及化学物质中毒主挂载相应化学毒物节点；涉及机械创伤主挂载创伤外科或相关临床科室。"}]}
